// Python `repr()` emulation for bytes objects.
// Reproduces CPython's formatting rules for `print(bytes_obj)`:
//   - single quotes by default; double quotes when the data contains a
//     single quote but no double quote
//   - escapes: \\, the active quote, \t, \n, \r
//   - printable ASCII (0x20-0x7E) shown verbatim
//   - everything else as \xhh (lowercase hex)

function hex2(n) {
  return n.toString(16).padStart(2, "0");
}

export function bytesRepr(bytes) {
  const hasSingle = bytes.includes(0x27); // '
  const hasDouble = bytes.includes(0x22); // "
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  const quoteChar = String.fromCharCode(quote);

  let out = "b" + quoteChar;
  for (const b of bytes) {
    if (b === 0x5c) {
      out += "\\\\";
    } else if (b === quote) {
      out += "\\" + quoteChar;
    } else if (b === 0x09) {
      out += "\\t";
    } else if (b === 0x0a) {
      out += "\\n";
    } else if (b === 0x0d) {
      out += "\\r";
    } else if (b >= 0x20 && b <= 0x7e) {
      out += String.fromCharCode(b);
    } else {
      out += "\\x" + hex2(b);
    }
  }
  out += quoteChar;
  return out;
}

