// Minimal reimplementation of the `construct` library features used here:
//   - construct.Int8ul.build(int)      -> one-byte unsigned little-endian build
//   - construct.Bytes(length).build(b) -> fixed-length byte string build
// Returns values are plain number arrays of bytes (0-255).

export class FormatFieldError extends Error {}
export class StreamError extends Error {}

// construct.Int8ul.build(value)
export function int8ulBuild(value) {
  if (!Number.isInteger(value) || value < 0 || value > 255) {
    throw new FormatFieldError(
      "Error in path (building)\n" +
        "struct '<B' error during building, given value " + String(value)
    );
  }
  return [value & 0xff];
}

// construct.Bytes(length).build(bytes)  -- bytes is a number array
export function fixedBytesBuild(length, bytes) {
  if (bytes.length !== length) {
    throw new StreamError(
      "Error in path (building)\n" +
        "bytes object of wrong length, expected " +
        String(length) +
        ", found " +
        String(bytes.length)
    );
  }
  return bytes.slice();
}

