// Minimal argparse-compatible CLI parsing for this script's options:
//   --a A (int, required), --b B (int, required), --c C (str, required)
// Mirrors argparse behavior: supports "--opt value" and "--opt=value",
// prints usage + error to stderr and exits with code 2 on failure.

const PROG = "test8_executable";
const USAGE = `usage: ${PROG} [-h] --a A --b B --c C`;

function fail(message) {
  process.stderr.write(USAGE + "\n");
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  process.stdout.write(USAGE + "\n\noptions:\n");
  process.stdout.write("  -h, --help  show this help message and exit\n");
  process.stdout.write("  --a A\n  --b B\n  --c C\n");
  process.exit(0);
}

// Python int(): optional surrounding whitespace, optional sign, digits
// (underscores between digits are also legal, e.g. "1_0").
function parseIntValue(raw, optName) {
  const text = String(raw).trim();
  if (!/^[+-]?\d(_?\d)*$/.test(text)) {
    fail(`argument ${optName}: invalid int value: '${raw}'`);
  }
  return parseInt(text.replace(/_/g, ""), 10);
}

export function parseArgs(argv) {
  const specs = [
    { name: "--a", key: "a", type: "int", metavar: "A" },
    { name: "--b", key: "b", type: "int", metavar: "B" },
    { name: "--c", key: "c", type: "str", metavar: "C" },
  ];
  const values = {};

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === "-h" || token === "--help") {
      printHelp();
    }

    let optToken = token;
    let inlineValue = null;
    const eq = token.indexOf("=");
    if (token.startsWith("--") && eq !== -1) {
      optToken = token.slice(0, eq);
      inlineValue = token.slice(eq + 1);
    }

    const spec = specs.find((s) => s.name === optToken);
    if (!spec) {
      fail(`unrecognized arguments: ${token}`);
    }

    let raw;
    if (inlineValue !== null) {
      raw = inlineValue;
    } else {
      i += 1;
      if (i >= argv.length) {
        fail(`argument ${spec.name}: expected one argument`);
      }
      raw = argv[i];
    }

    values[spec.key] =
      spec.type === "int" ? parseIntValue(raw, spec.name) : String(raw);
  }

  const missing = specs.filter((s) => !(s.key in values)).map((s) => s.name);
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(", ")}`);
  }

  return values;
}

