#!/usr/bin/env node
// Node.js ESM port of /workspace/dataset/construct/test8.py
import { parseArgs } from "./lib/argparse.mjs";
import { int8ulBuild, fixedBytesBuild } from "./lib/construct.mjs";
import { bytesRepr } from "./lib/pyrepr.mjs";

function main() {
  const args = parseArgs(process.argv.slice(2));

  const format1 = int8ulBuild(args.a); // build the first integer
  const format2 = int8ulBuild(args.b); // build the second integer
  // args.c encoded as UTF-8 bytes (str.encode() in Python)
  const encoded = Array.from(Buffer.from(args.c, "utf8"));
  const length = args.c.length; // Python len(str) counts code points... see below
  const format3 = fixedBytesBuild(length, encoded); // build the byte string

  console.log(bytesRepr(format1));
  console.log(bytesRepr(format2));
  console.log(bytesRepr(format3));
}

main();

